package io.forgeloop.control.application;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import io.forgeloop.control.domain.*; import java.util.*; import org.junit.jupiter.api.Test;
class RunnerServiceTest { RunnerRepository runners=mock(RunnerRepository.class); RunnerRegistrationTokenRepository tokens=mock(RunnerRegistrationTokenRepository.class); RunnerService service=new RunnerService(runners,tokens); @Test void issuesAndConsumesSingleUseToken() throws Exception {when(tokens.save(any())).thenAnswer(call->call.getArgument(0));String raw=service.issueRegistrationToken("org-1");RunnerRegistrationToken token=new RunnerRegistrationToken(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8))),"org-1",java.time.Instant.now().plusSeconds(60));when(tokens.findByTokenHash(any())).thenReturn(Optional.of(token));when(runners.save(any())).thenAnswer(call->call.getArgument(0));Runner runner=service.register(new RunnerRegistration(raw,"build-node","0.1.0",List.of("docker","git")));assertEquals("org-1",runner.getOrganizationId());assertThrows(IllegalStateException.class,()->service.register(new RunnerRegistration(raw,"other","0.1.0",List.of("git"))));} }
